+package ratelimit
+
+import (
+	"time"
+)
+
+// ClientState tracks the request count and window start for a single client.
+type ClientState struct {
+	Count     int
+	WindowStart time.Time
+}
+
+// RateLimiter enforces per-client request limits within a sliding time window.
+type RateLimiter struct {
+	clients    map[string]*ClientState
+	maxPerWindow int
+	windowDuration time.Duration
+}
+
+// New creates a RateLimiter that allows maxPerWindow requests within each window.
+func New(maxPerWindow int, windowDuration time.Duration) *RateLimiter {
+	return &RateLimiter{
+		clients:        make(map[string]*ClientState),
+		maxPerWindow:   maxPerWindow,
+		windowDuration: windowDuration,
+	}
+}
+
+// Allow checks whether the given client key is allowed to make another request.
+// It increments the counter and returns true if the client is within limits.
+func (rl *RateLimiter) Allow(clientKey string) bool {
+	now := time.Now()
+
+	state, exists := rl.clients[clientKey]
+	if !exists {
+		rl.clients[clientKey] = &ClientState{
+			Count:       1,
+			WindowStart: now,
+		}
+		return true
+	}
+
+	if now.Sub(state.WindowStart) > rl.windowDuration {
+		state.Count = 1
+		state.WindowStart = now
+		return true
+	}
+
+	if state.Count >= rl.maxPerWindow {
+		return false
+	}
+
+	state.Count++
+	return true
+}
+
+// Reset clears all tracked client state.
+func (rl *RateLimiter) Reset() {
+	rl.clients = make(map[string]*ClientState)
+}
